const h=this.helpers,H='https://old-hub.example/webhook/';
const S=v=>v==null?'':String(v).trim();
const B=$input.first().json.body||{};
const L=async t=>{const r=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t='+t,body:{},json:true});return Array.isArray(r)?r:[];};
const rams=(await L('rams')).sort((a,b)=>Number(b.id)-Number(a.id));
const r=rams.find(x=>S(x.pdf_url))||rams[0]||null;
let body;
if(B.nojob){body={event:'test_notification',job_no:'',message:'TEST notification with no job number - checking it lands on the Actions board. Set it to Done to clear it.',link:H+'cbs-admin?open=rams'+(r?'&id='+r.id:''),pdf:r?S(r.pdf_url):''};}
else{const job=S(B.job_no).replace(/[^0-9]/g,'')||(r?S(r.job_no).replace(/[^0-9]/g,''):'');
body={event:'test_notification',job_no:job,message:'TEST notification - checking the new note layout. Please ignore.'+(r?' (Links use RAMS #'+r.id+(r.activity||r.task?': '+S(r.activity||r.task):'')+'.)':''),sign:H+'cbs-sign?doc=rams&id='+(r?r.id:0),link:H+'cbs-admin?open=rams'+(r?'&id='+r.id:''),pdf:r?S(r.pdf_url):''};}
await h.httpRequest({method:'POST',url:H+'cbs-notify',body:body,json:true,timeout:15000});
return [{json:{sent:true,body:body}}];
